(()=>{function n(n){return n.toFixed(2)+" грн"}const t=document.getElementById("salary-input"),e=document.getElementById("salary-result"),r=document.getElementById("calculate-salary"),o=.18,i=.05;r.addEventListener("click",()=>{const r=document.querySelector('input[name="mode"]:checked').value,s=parseFloat(t.value);if(isNaN(s)||s<=0)return e.innerHTML="<p>Введіть коректну суму.</p>",void 0;!function(t){e.innerHTML=`\n      <p><strong>Нарахована зарплата (брутто):</strong> ${n(t.gross)}</p>\n      <p>ПДФО (18%): ${n(t.pit)}</p>\n      <p>Військовий збір (5%): ${n(t.military)}</p>\n      <p><strong>Сума до виплати (нетто):</strong> ${n(t.net)}</p>\n      <p>ЄСВ (22%, сплачує роботодавець): ${n(t.eru)}</p>\n    `}("gross"===r?function(n){const t=n*o,e=n*i;return{gross:n,pit:t,military:e,eru:.22*n,net:n-t-e}}(s):function(n){const t=n/.77;return{gross:t,pit:t*o,military:t*i,eru:.22*t,net:n}}(s))})})();